import{_ as n,a0 as h,w as p,s as d,I as e,x as s,a1 as t,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"GIT 命令“從初學到專業”完整進階指南 | LCTT x X-CMD","titleTemplate":false,"description":"GIT 命令“從初學到專業”完整進階指南 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GIT 命令“從初學到專業”完整進階指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GIT 命令“從初學到專業”完整進階指南 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20170730 Complete Beginners to PRO guide for GIT commands","title":"GIT 命令“從初學到專業”完整進階指南","tag":"201712","desc":""},"relativePath":"201712/20170730 Complete Beginners to PRO guide for GIT commands.md","filePath":"[post].md"}'),g={name:"201712/20170730 Complete Beginners to PRO guide for GIT commands.md"};function o(k,i,c,b,u,f){const a=h("Link");return p(),d("div",null,[i[18]||(i[18]=e("h1",{id:"git-命令-從初學到專業-完整進階指南",tabindex:"-1"},[s("GIT 命令“從初學到專業”完整進階指南 "),e("a",{class:"header-anchor",href:"#git-命令-從初學到專業-完整進階指南","aria-label":"Permalink to “GIT 命令“從初學到專業”完整進階指南”"},"​")],-1)),e("p",null,[i[1]||(i[1]=s("在",-1)),t(a,{href:"http://linuxtechlab.com/install-git-linux-ubuntu-centos/"},{default:l(()=>[...i[0]||(i[0]=[s("之前的教程",-1)])]),_:1}),i[2]||(i[2]=s("中，我們已經學習了在機器上安裝 git。本教程，我們將討論如何使用 git，比如與 git 一起使用的各種命令。所以我們開始吧，",-1))]),e("ul",null,[e("li",null,[i[4]||(i[4]=s("推薦閲讀：",-1)),t(a,{href:"http://linuxtechlab.com/install-git-linux-ubuntu-centos/"},{default:l(()=>[...i[3]||(i[3]=[s("如何在 Linux 上安裝 GIT (Ubuntu 和 CentOS)",-1)])]),_:1})])]),i[19]||(i[19]=r(`<h3 id="設置用户信息" tabindex="-1">設置用户信息 <a class="header-anchor" href="#設置用户信息" aria-label="Permalink to “設置用户信息”">​</a></h3><p>這應該是安裝完 git 的第一步。我們將添加用户信息 (用户名和郵箱)，所以當我們提交代碼時，會產生帶有用户信息的提交信息，這使得跟蹤提交過程變得更容易。要添加用户信息，命令是 <code>git config</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global user.name &quot;Daniel&quot;</span></span>
<span class="line"><span>$ git config --global user.email &quot;dan.mike@xyz.com&quot;</span></span></code></pre></div><p>添加完用户信息之後，通過運行下面命令，我們將檢查這些信息是否成功更新。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --list</span></span></code></pre></div><p>我們應該能夠看到輸出的用户信息。</p><h3 id="git-命令" tabindex="-1">GIT 命令 <a class="header-anchor" href="#git-命令" aria-label="Permalink to “GIT 命令”">​</a></h3><h4 id="新建一個倉庫" tabindex="-1">新建一個倉庫 <a class="header-anchor" href="#新建一個倉庫" aria-label="Permalink to “新建一個倉庫”">​</a></h4><p>為了建立一個新倉庫，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git init</span></span></code></pre></div><h4 id="查找一個倉庫" tabindex="-1">查找一個倉庫 <a class="header-anchor" href="#查找一個倉庫" aria-label="Permalink to “查找一個倉庫”">​</a></h4><p>為了查找一個倉庫，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git grep &quot;repository&quot;</span></span></code></pre></div><h4 id="與遠程倉庫連接" tabindex="-1">與遠程倉庫連接 <a class="header-anchor" href="#與遠程倉庫連接" aria-label="Permalink to “與遠程倉庫連接”">​</a></h4><p>為了與遠程倉庫連接，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add origin remote_server</span></span></code></pre></div><p>然後檢查所有配置的遠程服務器，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote -v</span></span></code></pre></div><h4 id="克隆一個倉庫" tabindex="-1">克隆一個倉庫 <a class="header-anchor" href="#克隆一個倉庫" aria-label="Permalink to “克隆一個倉庫”">​</a></h4><p>為了從本地服務器克隆一個倉庫，運行如下代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone repository_path</span></span></code></pre></div><p>如果我們想克隆遠程服務器上的一個倉庫，那克隆這個倉庫的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone repository_path</span></span></code></pre></div><h4 id="在倉庫中列出分支" tabindex="-1">在倉庫中列出分支 <a class="header-anchor" href="#在倉庫中列出分支" aria-label="Permalink to “在倉庫中列出分支”">​</a></h4><p>為了檢查所有可用的和當前工作的分支列表，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git branch</span></span></code></pre></div><h4 id="創建新分支" tabindex="-1">創建新分支 <a class="header-anchor" href="#創建新分支" aria-label="Permalink to “創建新分支”">​</a></h4><p>創建並使用一個新分支，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout -b &#39;branchname&#39;</span></span></code></pre></div><h4 id="刪除一個分支" tabindex="-1">刪除一個分支 <a class="header-anchor" href="#刪除一個分支" aria-label="Permalink to “刪除一個分支”">​</a></h4><p>為了刪除一個分支，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git branch -d &#39;branchname&#39;</span></span></code></pre></div><p>為了刪除遠程倉庫的一個分支，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push origin:&#39;branchname&#39;</span></span></code></pre></div><h4 id="切換到另一個分支" tabindex="-1">切換到另一個分支 <a class="header-anchor" href="#切換到另一個分支" aria-label="Permalink to “切換到另一個分支”">​</a></h4><p>從當前分支切換到另一個分支，使用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout &#39;branchname&#39;</span></span></code></pre></div><h4 id="添加文件" tabindex="-1">添加文件 <a class="header-anchor" href="#添加文件" aria-label="Permalink to “添加文件”">​</a></h4><p>添加文件到倉庫，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add filename</span></span></code></pre></div><h4 id="文件狀態" tabindex="-1">文件狀態 <a class="header-anchor" href="#文件狀態" aria-label="Permalink to “文件狀態”">​</a></h4><p>檢查文件狀態 (那些將要提交或者添加的文件)，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git status</span></span></code></pre></div><h4 id="提交變更" tabindex="-1">提交變更 <a class="header-anchor" href="#提交變更" aria-label="Permalink to “提交變更”">​</a></h4><p>在我們添加一個文件或者對一個文件作出變更之後，我們通過運行下面命令來提交代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git commit -a</span></span></code></pre></div><p>提交變更到 head 但不提交到遠程倉庫，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git commit -m &quot;message&quot;</span></span></code></pre></div><h4 id="推送變更" tabindex="-1">推送變更 <a class="header-anchor" href="#推送變更" aria-label="Permalink to “推送變更”">​</a></h4><p>推送對該倉庫 master 分支所做的變更，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push origin master</span></span></code></pre></div><h4 id="推送分支到倉庫" tabindex="-1">推送分支到倉庫 <a class="header-anchor" href="#推送分支到倉庫" aria-label="Permalink to “推送分支到倉庫”">​</a></h4><p>推送對單一分支做出的變更到遠程倉庫，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push origin &#39;branchname&#39;</span></span></code></pre></div><p>推送所有分支到遠程倉庫，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push -all origin</span></span></code></pre></div><h4 id="合併兩個分支" tabindex="-1">合併兩個分支 <a class="header-anchor" href="#合併兩個分支" aria-label="Permalink to “合併兩個分支”">​</a></h4><p>合併另一個分支到當前活動分支，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git merge &#39;branchname&#39;</span></span></code></pre></div><h4 id="從遠端服務器合併到本地服務器" tabindex="-1">從遠端服務器合併到本地服務器 <a class="header-anchor" href="#從遠端服務器合併到本地服務器" aria-label="Permalink to “從遠端服務器合併到本地服務器”">​</a></h4><p>從遠端服務器下載/拉取變更到到本地服務器的工作目錄，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git pull</span></span></code></pre></div><h4 id="檢查合併衝突" tabindex="-1">檢查合併衝突 <a class="header-anchor" href="#檢查合併衝突" aria-label="Permalink to “檢查合併衝突”">​</a></h4><p>查看對庫文件的合併衝突，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git diff -base &#39;filename&#39;</span></span></code></pre></div><p>查看所有衝突，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git diff</span></span></code></pre></div><p>如果我們在合併之前想預覽所有變更，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git diff &#39;source-branch&#39; &#39;target-branch&#39;</span></span></code></pre></div><h4 id="創建標記" tabindex="-1">創建標記 <a class="header-anchor" href="#創建標記" aria-label="Permalink to “創建標記”">​</a></h4><p>創建標記來標誌任一重要的變更，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git tag &#39;tag number&#39; &#39;commit id&#39;</span></span></code></pre></div><p>通過運行以下命令，我們可以查找 commit id ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log</span></span></code></pre></div><h4 id="推送標記" tabindex="-1">推送標記 <a class="header-anchor" href="#推送標記" aria-label="Permalink to “推送標記”">​</a></h4><p>推送所有創建的標記到遠端服務器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push -tags origin</span></span></code></pre></div><h4 id="回覆做出的變更" tabindex="-1">回覆做出的變更 <a class="header-anchor" href="#回覆做出的變更" aria-label="Permalink to “回覆做出的變更”">​</a></h4><p>如果我們想用 head 中最後一次變更來替換對當前工作樹的變更，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout -&#39;filename&#39;</span></span></code></pre></div><p>我們也可以從遠端服務器獲取最新的歷史，並且將它指向本地倉庫的 master 分支,而不是丟棄掉所有本地所做所有變更。為了這麼做，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git fetch origin</span></span>
<span class="line"><span>$ git reset -hard master</span></span></code></pre></div><p>好了，夥計們。這些就是我們使用 git 服務器的命令。我們將會很快為大家帶來更有趣的教程。如果你希望我們對某個特定話題寫一個教程，請通過下面的評論箱告訴我們。像往常一樣， 歡迎您的各種意見和建議。</p><hr>`,84)),e("p",null,[i[6]||(i[6]=s("via: ",-1)),t(a,{href:"http://linuxtechlab.com/beginners-to-pro-guide-for-git-commands/"},{default:l(()=>[...i[5]||(i[5]=[s("http://linuxtechlab.com/beginners-to-pro-guide-for-git-commands/",-1)])]),_:1})]),e("p",null,[i[10]||(i[10]=s("作者：",-1)),t(a,{href:"http://linuxtechlab.com/author/shsuain/"},{default:l(()=>[...i[7]||(i[7]=[s("Shusain",-1)])]),_:1}),i[11]||(i[11]=s(" 譯者：",-1)),t(a,{href:"https://github.com/liuxinyu123"},{default:l(()=>[...i[8]||(i[8]=[s("liuxinyu123",-1)])]),_:1}),i[12]||(i[12]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[9]||(i[9]=[s("wxy",-1)])]),_:1})]),e("p",null,[i[15]||(i[15]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...i[14]||(i[14]=[s("Linux中國",-1)])]),_:1}),i[17]||(i[17]=s(" 榮譽推出",-1))])])}const x=n(g,[["render",o]]);export{C as __pageData,x as default};
